  "home.majorEconomiesTitle": { en: "Major Economies", tr: "Başlıca Ekonomiler", de: "Wichtige Volkswirtschaften", fr: "Grandes économies", es: "Grandes economías", ar: "الاقتصادات الكبرى", zh: "主要经济体", ru: "Крупные экономики" },
  "home.majorEconomiesDesc": { en: "The 20 largest advanced economies compared country by country, rather than aggregated into a bloc.", tr: "En büyük 20 gelişmiş ekonomi, bir blokta toplanmak yerine ülke ülke karşılaştırılır.", de: "Die 20 größten fortgeschrittenen Volkswirtschaften, Land für Land verglichen statt in einem Block zusammengefasst.", fr: "Les 20 plus grandes économies avancées, comparées pays par pays plutôt qu'agrégées en un bloc.", es: "Las 20 economías avanzadas más grandes, comparadas país por país en lugar de agregarse en un bloque.", ar: "أكبر 20 اقتصادًا متقدمًا تُقارَن دولة بدولة بدلًا من تجميعها في كتلة.", zh: "20个最大发达经济体逐一国别对比，而非合并为集团。", ru: "20 крупнейших развитых экономик, сопоставленных по странам, а не свёрнутых в блок." },
  "home.riskTitle": { en: "Global Risk Simulator", tr: "Global Risk Simulator", de: "Global Risk Simulator", fr: "Global Risk Simulator", es: "Global Risk Simulator", ar: "Global Risk Simulator", zh: "Global Risk Simulator", ru: "Global Risk Simulator" },
  "home.riskDesc": { en: "How countries rank under six different global-crisis scenarios. The same country data, a different ranking per scenario.", tr: "Ülkelerin altı farklı küresel kriz senaryosundaki sıralaması. Aynı ülke verisi, senaryoya göre farklı bir sıralama.", de: "Wie Länder unter sechs verschiedenen globalen Krisenszenarien abschneiden. Dieselbe Länderdatenbasis, eine andere Rangliste pro Szenario.", fr: "Le classement des pays selon six scénarios de crise mondiale différents. Les mêmes données, un classement différent par scénario.", es: "Cómo se clasifican los países bajo seis escenarios distintos de crisis mundial. Los mismos datos, una clasificación diferente por escenario.", ar: "ترتيب الدول تحت ستة سيناريوهات مختلفة للأزمات العالمية. البيانات نفسها وترتيب مختلف لكل سيناريو.", zh: "各国在六种全球危机情景下的排名。同一套国别数据，不同情景得出不同排名。", ru: "Как страны ранжируются в шести различных сценариях мирового кризиса. Те же данные, разный порядок в каждом сценарии." },
  "home.tensionTitle": { en: "Current Tension", tr: "Current Tension", de: "Current Tension", fr: "Current Tension", es: "Current Tension", ar: "Current Tension", zh: "Current Tension", ru: "Current Tension" },
  "home.tensionDesc": { en: "A live conflict/cooperation signal from the GDELT 2.0 Event Database, refreshed every few hours. An interpretation, not a forecast.", tr: "GDELT 2.0 Olay Veritabanından gelen canlı çatışma/iş birliği sinyali; birkaç saatte bir güncellenir. Bir yorumdur, tahmin değil.", de: "Ein live Konflikt-/Kooperationssignal aus der GDELT-2.0-Ereignisdatenbank, alle paar Stunden aktualisiert. Eine Interpretation, keine Prognose.", fr: "Un signal en direct de conflit/coopération issu de la base d'événements GDELT 2.0, actualisé toutes les quelques heures. Une interprétation, pas une prévision.", es: "Una señal en directo de conflicto/cooperación de la base de eventos GDELT 2.0, actualizada cada pocas horas. Una interpretación, no una previsión.", ar: "إشارة حية للنزاع والتعاون من قاعدة بيانات أحداث GDELT 2.0، تُحدَّث كل بضع ساعات. تفسير لا تنبؤ.", zh: "来自GDELT 2.0事件数据库的实时冲突/合作信号，每数小时刷新。属于解读，不是预测。", ru: "Живой сигнал конфликта/сотрудничества из базы событий GDELT 2.0, обновляемый каждые несколько часов. Интерпретация, а не прогноз." },
  "home.hubTitle": { en: "Geo Analysis Hub", tr: "Geo Analysis Hub", de: "Geo Analysis Hub", fr: "Geo Analysis Hub", es: "Geo Analysis Hub", ar: "Geo Analysis Hub", zh: "Geo Analysis Hub", ru: "Geo Analysis Hub" },
  "home.hubDesc": { en: "Global Monitor, Current Tension, the Risk Simulator, Worldora and Worldora Intelligence together, as one interactive slider.", tr: "Global Monitor, Current Tension, Risk Simulator, Worldora ve Worldora Intelligence bir arada; tek bir etkileşimli slayt olarak.", de: "Global Monitor, Current Tension, Risk Simulator, Worldora und Worldora Intelligence gemeinsam als ein interaktiver Slider.", fr: "Global Monitor, Current Tension, Risk Simulator, Worldora et Worldora Intelligence réunis en un curseur interactif.", es: "Global Monitor, Current Tension, Risk Simulator, Worldora y Worldora Intelligence juntos, como un control deslizante interactivo.", ar: "‏Global Monitor وCurrent Tension وRisk Simulator وWorldora وWorldora Intelligence معًا في شريط تفاعلي واحد.", zh: "Global Monitor、Current Tension、Risk Simulator、Worldora 与 Worldora Intelligence 汇聚为一个交互式滑块。", ru: "Global Monitor, Current Tension, Risk Simulator, Worldora и Worldora Intelligence вместе - как один интерактивный слайдер." },

