  "compare.description": { en: "Compare {a} and {b} across economic, trade, social, and military data.", tr: "{a} ve {b} arasındaki ekonomik, ticari, sosyal ve askeri verileri karşılaştırın.", de: "{a} und {b} nach wirtschaftlichen, handels-, sozial- und militärischen Daten vergleichen.", fr: "Comparer {a} et {b} sur les données économiques, commerciales, sociales et militaires.", es: "Comparar {a} y {b} en datos económicos, comerciales, sociales y militares.", ar: "قارن بين {a} و{b} في البيانات الاقتصادية والتجارية والاجتماعية والعسكرية.", zh: "在经济、贸易、社会与军事数据上对比{a}与{b}。", ru: "Сравнить {a} и {b} по экономическим, торговым, социальным и военным данным." },
  "compare.seeAllDimensions": { en: "See {dim} data across all blocs →", tr: "Tüm bloklardaki {dim} verisini görün →", de: "{dim}-Daten über alle Blöcke ansehen →", fr: "Voir les données {dim} pour tous les blocs →", es: "Ver los datos de {dim} en todos los bloques →", ar: "اطلع على بيانات {dim} عبر جميع الكتل ←", zh: "查看所有集团的{dim}数据 →", ru: "Посмотреть данные по «{dim}» для всех блоков →" },

