  "tension.aria.score": { en: "Mean Goldstein score {value} out of a possible minus 10 to plus 10, i.e. {verdict} {pole}", tr: "Olası -10 ile +10 arasında ortalama Goldstein skoru {value}, yani {verdict} {pole}", de: "Mittlerer Goldstein-Wert {value} von möglichen minus 10 bis plus 10, d. h. {verdict} {pole}", fr: "Score de Goldstein moyen {value} sur une échelle de moins 10 à plus 10, soit {verdict} {pole}", es: "Puntuación media de Goldstein {value} en una escala de -10 a +10, es decir, {verdict} {pole}", ar: "متوسط درجة Goldstein ‎{value}‎ من مئة تتراوح بين -10 و+10، أي {verdict} {pole}", zh: "平均Goldstein得分为{value}（满分范围-10至+10），即{verdict}{pole}", ru: "Средний балл Голдштейна {value} из возможных минус 10 до плюс 10, то есть {verdict} {pole}" },
