  "tension.query.bilateralWindow": { en: "{n} bilateral events in the last {h}h", tr: "Son {h} saatte {n} ikili olay", de: "{n} bilaterale Ereignisse in den letzten {h} Std.", fr: "{n} événements bilatéraux au cours des dernières {h} h", es: "{n} eventos bilaterales en las últimas {h} h", ar: "{n} حدثًا ثنائيًا خلال آخر {h} ساعة", zh: "最近{h}小时内{n}起双边事件", ru: "{n} двусторонних событий за последние {ч} ч." },
