  "tension.table.conflictShare": { en: "Conflict share", tr: "Çatışma payı", de: "Konfliktanteil", fr: "Part du conflit", es: "Cuota de conflicto", ar: "حصة النزاع", zh: "冲突占比", ru: "Доля конфликта" },
