  "tension.table.materialConflict": { en: "Material conflict events", tr: "Maddi çatışma olayları", de: "Materielle Konflikttereignisse", fr: "Événements de conflit matériel", es: "Eventos de conflicto material", ar: "أحداث النزاع المادي", zh: "实质冲突事件", ru: "События материального конфликта" },
