  "gauge.conflict": { en: "Conflict", tr: "Çatışma", de: "Konflikt", fr: "Conflit", es: "Conflicto", ar: "صراع", zh: "冲突", ru: "Конфликт" },
  "gauge.cooperation": { en: "Cooperation", tr: "İş birliği", de: "Kooperation", fr: "Coopération", es: "Cooperación", ar: "تعاون", zh: "合作", ru: "Сотрудничество" },
